        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug occurs because the DMA mapping for the `skb` is not being released when the `push_scqe` function fails to submit the `skb`. As a result, the memory associated with the `skb` is freed, but the corresponding DMA mapping remains, leading to a memory leak.

        Commit message:
        atm: nicstar: Unmap DMA on send error

The `skb' is mapped for DMA in ns_send() but does not unmap DMA in case
push_scqe() fails to submit the `skb'. The memory of the `skb' is
released so only the DMA mapping is leaking.

Unmap the DMA mapping in case push_scqe() failed.

Fixes: 864a3ff635fa7 ("atm: [nicstar] remove virt_to_bus() and support 64-bit platforms")
Cc: Chas Williams <3chas3@gmail.com>
Signed-off-by: Sebastian Andrzej Siewior <bigeasy@linutronix.de>
Signed-off-by: Jakub Kicinski <kuba@kernel.org>  

        Patch:

 static int ns_send(struct atm_vcc *vcc, struct sk_buff *skb)
 {
 	ns_dev *card;
 	vc_map *vc;
 	scq_info *scq;
 	unsigned long buflen;
 	ns_scqe scqe;
 	u32 flags;		/* TBD flags, not CPU flags */

 	card = vcc->dev->dev_data;
 	TXPRINTK("nicstar%d: ns_send() called.\n", card->index);
 	if ((vc = (vc_map *) vcc->dev_data) == NULL) {
 		printk("nicstar%d: vcc->dev_data == NULL on ns_send().\n",
 		       card->index);
 		atomic_inc(&vcc->stats->tx_err);
 		dev_kfree_skb_any(skb);
 		return -EINVAL;
 	}

 	if (!vc->tx) {
 		printk("nicstar%d: Trying to transmit on a non-tx VC.\n",
 		       card->index);
 		atomic_inc(&vcc->stats->tx_err);
 		dev_kfree_skb_any(skb);
 		return -EINVAL;
 	}

 	if (vcc->qos.aal != ATM_AAL5 && vcc->qos.aal != ATM_AAL0) {
 		printk("nicstar%d: Only AAL0 and AAL5 are supported.\n",
 		       card->index);
 		atomic_inc(&vcc->stats->tx_err);
 		dev_kfree_skb_any(skb);
 		return -EINVAL;
 	}

 	if (skb_shinfo(skb)->nr_frags != 0) {
 		printk("nicstar%d: No scatter-gather yet.\n", card->index);
 		atomic_inc(&vcc->stats->tx_err);
 		dev_kfree_skb_any(skb);
 		return -EINVAL;
 	}

 	ATM_SKB(skb)->vcc = vcc;

 	NS_PRV_DMA(skb) = dma_map_single(&card->pcidev->dev, skb->data,
 					 skb->len, DMA_TO_DEVICE);

 	if (vcc->qos.aal == ATM_AAL5) {
 		buflen = (skb->len + 47 + 8) / 48 * 48;	/* Multiple of 48 */
 		flags = NS_TBD_AAL5;
 		scqe.word_2 = cpu_to_le32(NS_PRV_DMA(skb));
 		scqe.word_3 = cpu_to_le32(skb->len);
 		scqe.word_4 =
 		    ns_tbd_mkword_4(0, (u32) vcc->vpi, (u32) vcc->vci, 0,
 				    ATM_SKB(skb)->
 				    atm_options & ATM_ATMOPT_CLP ? 1 : 0);
 		flags |= NS_TBD_EOPDU;
 	} else {		/* (vcc->qos.aal == ATM_AAL0) */

 		buflen = ATM_CELL_PAYLOAD;	/* i.e., 48 bytes */
 		flags = NS_TBD_AAL0;
 		scqe.word_2 = cpu_to_le32(NS_PRV_DMA(skb) + NS_AAL0_HEADER);
 		scqe.word_3 = cpu_to_le32(0x00000000);
 		if (*skb->data & 0x02)	/* Payload type 1 - end of pdu */
 			flags |= NS_TBD_EOPDU;
 		scqe.word_4 =
 		    cpu_to_le32(*((u32 *) skb->data) & ~NS_TBD_VC_MASK);
 		/* Force the VPI/VCI to be the same as in VCC struct */
 		scqe.word_4 |=
 		    cpu_to_le32((((u32) vcc->
 				  vpi) << NS_TBD_VPI_SHIFT | ((u32) vcc->
 							      vci) <<
 				 NS_TBD_VCI_SHIFT) & NS_TBD_VC_MASK);
 	}

 	if (vcc->qos.txtp.traffic_class == ATM_CBR) {
 		scqe.word_1 = ns_tbd_mkword_1_novbr(flags, (u32) buflen);
 		scq = ((vc_map *) vcc->dev_data)->scq;
 	} else {
 		scqe.word_1 =
 		    ns_tbd_mkword_1(flags, (u32) 1, (u32) 1, (u32) buflen);
 		scq = card->scq0;
 	}

 	if (push_scqe(card, vc, scq, &scqe, skb) != 0) {
 		atomic_inc(&vcc->stats->tx_err);
+		dma_unmap_single(&card->pcidev->dev, NS_PRV_DMA(skb), skb->len,
+				 DMA_TO_DEVICE);
 		dev_kfree_skb_any(skb);
 		return -EIO;
 	}
 	atomic_inc(&vcc->stats->tx);

 	return 0;
 }



